class SourceReads:
    """Share concurrent reads, never serve a completed live URL as fresh evidence."""
    def __init__(self, limit=4):
        self.pending = {}
        self.gate = asyncio.Semaphore(limit)
        self.stats = {"loads": 0, "shared": 0}

